D='/tmp/oaimath/158/entry'; os.chdir(D)
def edit(fn, pairs):
    s=open(fn,encoding='utf-8').read()
    for old,new in pairs:
        if s.count(old)==0 and new in s: continue   # already applied
        assert s.count(old)==1, (fn, s.count(old), old[:70])
        s=s.replace(old,new)
    open(fn,'w',encoding='utf-8').write(s)
